func (this *ToolBar) translateTraversal_(key int32, theEvent *cocoa.NSEvent, consume []bool) bool {
	var result bool = this.Composite.translateTraversal_(key, theEvent, consume)
	if result {
		return result
	}
	var next bool = false
	var checkPopup bool = false
	switch key {
	case 123:
		next = false
		break
	case 124:
		next = true
		break
	case 126:
		next = false
		checkPopup = true
		break
	case 125:
		next = true
		checkPopup = true
		break
	default:
		return false
	}
	consume[0] = true
	if checkPopup && this.lastFocus != (nil) {
		if this.lastFocus.HandleKeyDown() {
			return false
		}
	}
	var items []*ToolItem = this.GetItems()
	var item *ToolItem = this.lastFocus
	var length int32 = int32(len(items))
	var index int32 = 0
	for index < length {
		if items[index] == item {
			break
		}
		index++
	}
	if index == length {
		return false
	}
	var start int32 = index
	var offset int32
	if next {
		offset = 1
	} else {
		offset = -1
	}
	for {
		cond607 := (index + offset + length) % length
		index = cond607
		if !((cond607) != start) {
			break
		}
		var child *ToolItem = items[index]
		if !child.IsDisposed() {
			if child.SetFocus() {
				this.lastFocus = child
				return false
			}
		}
	}
	return false
}

func ToolBarCheckStyle(parentLike CompositeLike, style int32, internal bool) int32 {
	var parent *Composite
	if parentLike != nil {
		parent = parentLike.AsComposite()
	}
	_ = parent
	var newStyle int32 = style & ^(H_SCROLL | V_SCROLL)
	if !internal && (newStyle&SMOOTH) != 0 {
		newStyle &= ^SMOOTH
	}
	if (style & SMOOTH) != 0 {
		s, ok608 := isCompositeToShell(parent)
		if ok608 {
			if s.window.Toolbar() != (nil) {
				newStyle &= ^SMOOTH
			}
		} else {
			newStyle &= ^SMOOTH
		}
	}
	if (newStyle & SMOOTH) != 0 {
		newStyle &= ^(VERTICAL | WRAP)
		newStyle |= HORIZONTAL
	}
	return newStyle
}

